L000048	\title{Dynamic redundancy and mortality in stochastic search}
L000049	
L000050	
L000051	\author{Samantha Linn}
L000052	\email{s.linn@imperial.ac.uk}
L000053	\affiliation{Department of Mathematics, Imperial College London, London SW7 2AZ, UK}
L000054	
L000055	\author{Aanjaneya Kumar}
L000056	\email{aanjaneya@santafe.edu}
L000057	\affiliation{Santa Fe Institute, 1399 Hyde Park Road, Santa Fe, NM 87501, USA}
L000058	\affiliation{High Meadows Environmental Institute, Princeton University, Princeton, NJ, 08544, USA}
