L000462	\section{High-turnover behavior of the FPT coefficient of variation is unity}
L000463	Consider a DRM search process with $\lambda = \alpha r$ and $\mu=r$. We can describe the coefficient of variation (CV) of the DRM FPT $T_{\alpha r,r}$, which we denote by $CV(T_{\alpha r,r})$, in terms of the corresponding survival probability $S_{\alpha r,r}(t)$,
L000464	\begin{align} \label{cv}
L000465	    CV^2(T_{\alpha r,r}) + 1 = \frac{2\int_0^\infty tS_{\alpha r,r}(t)\,\textup{d}t}{\big( \int_0^\infty S_{\alpha r,r}(t)\,\textup{d}t \big)^2} =: f(r).
L000466	\end{align}
L000467	Below we establish that $f(r)\sim 2$ as $r\to\infty$ which implies that the CV converges to unity in the high-turnover limit. We have already shown that for all $r>0$
L000468	\begin{align} \label{avg}
L000469	    \frac{1-p_r}{\alpha rp_r} \leq \int_0^\infty S_{\alpha r,r}(t)\,\textup{d}t \leq \frac{1-p_r}{\alpha rp_r} - \frac{\partial}{\partial r} \log p_r.
L000470	\end{align}
L000471	Moreover, since $S_{\alpha r,r}(t) \geq (1-p_r)e^{-\alpha rp_rt}$ it follows that
L000472	\begin{align} \label{lowb}
L000473	    \int_0^\infty tS_{\alpha r,r}(t)\,\textup{d}t \geq \frac{1-p_r}{(\alpha rp_r)^2}.
L000474	\end{align}
L000475	Combining the upper bound in Eq.~\eqref{avg} with Eq.~\eqref{lowb}, we have
L000476	\begin{align} \label{frlow}
L000477	    f(r) \geq \frac{2(1-p_r)/(\alpha rp_r)^2}{\Big(\frac{1-p_r}{\alpha rp_r} - \frac{\partial}{\partial r} \log p_r\Big)^2}.
L000478	\end{align}
L000479	Taking $r\to\infty$ yields $\liminf_{r\to\infty} f(r) = 2$. The limit supremum is more involved. Recall from Eq.~\eqref{s0mu} that $S_{0,r}(t) = 1-p_r+R_r(t)$ with $R_r(t)$ as in Eq.~\eqref{Rmu}. Then
L000480	\begin{align} \label{intsum}
L000481	    \int_0^\infty tS_{\alpha r,r}(t)\,\textup{d}t = \frac{1-p_r}{p_r}\int_0^\infty t(p_r-R_r(t))G_r(t)\,\textup{d}t + \frac{1}{p_r}\int_0^\infty tR_r(t)G_r(t)\,\textup{d}t.
L000482	\end{align}
L000483	Using Eq.~\eqref{avg} and $G_r(t)$ as defined in Eq.~\eqref{eq:Gdef} we determine an upper bound on the first integral in Eq.~\eqref{intsum},
L000484	\begin{align}
L000485	    \int_0^\infty t(p_r-R_r(t))G_r(t)\,\textup{d}t = \frac{-1}{\alpha r} \int_0^\infty tG_r'(t)\,\textup{d}t
L000486	    = \frac{1}{\alpha r}\int_0^\infty G_r(t)\,\textup{d}t
L000487	    \leq \frac{1}{\alpha r}\Big( \frac{1}{\alpha r} + \frac{1-p_r}{\alpha rp_r} - \frac{\partial}{\partial r} \log p_r \Big).
L000488	\end{align}
L000489	As for the second integral in Eq.~\eqref{intsum}, assume the density of the classical FPT $\tau>0$ has strictly positive support (\emph{e.g.} Brownian search). In this case,
L000490	\begin{align}
L000491	    R_r(t) = \int_t^\infty e^{-rs}\mathbb{P}(\tau=s)\,\textup{d}s
L000492	    \leq ||\mathbb{P}(\tau=s)||_\infty \int_t^\infty e^{-rs}\,\textup{d}s
L000493	    = \frac{||\mathbb{P}(\tau=s)||_\infty}{r} e^{-rt}
L000494	\end{align}
L000495	which is finite for all $r>0$. Using this inequality, we have
L000496	\begin{align}
L000497	    \int_0^\infty tR_r(t)G_r(t)\,\textup{d}t \leq \frac{||\mathbb{P}(\tau=s)||_\infty}{r} \int_0^\infty t e^{-rt}G_r(t)\,\textup{d}t
L000498	    \leq \frac{||\mathbb{P}(\tau=s)||_\infty}{r} \int_0^\infty t e^{-rt}\,\textup{d}t
L000499	    = \frac{||\mathbb{P}(\tau=s)||_\infty}{r^3}.
L000500	\end{align}
L000501	The upper bound on Eq.~\eqref{intsum} in its entirety is then described by
L000502	\begin{align}
L000503	    \int_0^\infty tS_{\alpha r,r}(t)\,\textup{d}t \leq \frac{1-p_r}{\alpha rp_r}\Big( \frac{1}{\alpha r} + \frac{1-p_r}{\alpha rp_r} - \frac{\partial}{\partial r} \log p_r \Big) + \frac{||\mathbb{P}(\tau=s)||_\infty}{r^3p_r}.
L000504	\end{align}
L000505	Hence,
L000506	\begin{align} \label{frupper}
L000507	    f(r) \leq 2\Big( \frac{\alpha rp_r}{1-p_r} \Big)\Big( \frac{1}{\alpha r} + \frac{1-p_r}{\alpha rp_r} - \frac{\partial}{\partial r} \log p_r \Big) + \frac{2\alpha^2 p_r||\mathbb{P}(\tau=s)||_\infty}{r(1-p_r)^2}.
L000508	\end{align}
L000509	Taking $r\to\infty$ yields $\limsup_{r\to\infty} f(r)=2$. Combining the limits infimum and supremum gives the desired result. In Fig.~\ref{fig:cv} we numerically compute the CV by way of Eq.~\eqref{cv} and illustrate how it evolves with respect to the turnover rate $r$. Regardless of the scaling factor $\alpha$, we see that the CV converges to one in the high turnover limit.
L000510	\begin{figure}[t!]
L000511	    \centering
L000512	    \includegraphics[width=.48\linewidth]{CV.png}
L000513	    \caption{DRM MFPT coefficient of variation (CV) for Brownian motion on the half line with $\lambda=\alpha r$ and $\mu=r$. The solid curves indicate the CV computed from Eq.~\eqref{cv} via quadrature. The dash-dot curves indicate the lower bound as in Eq.~\eqref{frlow} and the dashed curves indicate the upper bound as in Eq.~\eqref{frupper}. Here, $x_0=1$ and $D=1$. Evidently, for moderate to large values of $r$, CV is close to $1$, and for large $r$, CV $\to 1$.}
L000514	    \label{fig:cv}
L000515	\end{figure}
